.ps-summary{position:fixed;z-index:50;right:22px;bottom:16px;width:min(620px,calc(100vw - 300px));padding:10px 14px;display:grid;grid-template-columns:1.25fr 1.45fr 1fr;align-items:center;gap:10px;border:1px solid #bbc6ce;border-radius:14px;background:rgba(255,255,255,.97);box-shadow:0 14px 36px rgba(22,37,51,.18);backdrop-filter:blur(12px)}.ps-summary-toggle{position:absolute;top:-13px;right:16px;min-width:27px;height:27px;padding:0 8px;border:1px solid #bbc6ce;border-radius:99px;color:#00416b;background:#fff;box-shadow:0 3px 8px rgba(22,37,51,.12)}.ps-summary.collapsed{width:auto;padding:0;display:block;border:0;background:transparent;box-shadow:none}.ps-summary.collapsed>*:not(.ps-summary-toggle){display:none}.ps-summary.collapsed .ps-summary-toggle{position:static;height:36px;padding:0 15px}.ps-summary-title{display:grid;grid-template-columns:33px 1fr auto;align-items:center;gap:8px}.ps-summary-icon{width:33px;height:33px;display:grid;place-items:center;border-radius:9px;color:#fff;background:#00416b;font-size:16px}.ps-summary-title small,.ps-summary-title strong{display:block}.ps-summary-title small,.ps-summary-current small{color:#667085;font-size:7px;text-transform:uppercase}.ps-summary-title strong{color:#00416b;font-size:10px}.ps-live{padding:4px 7px;border-radius:99px;color:#087655;background:#e7f8f2;font-size:8px;font-weight:800}.ps-live i{width:5px;height:5px;margin-right:3px;display:inline-block;border-radius:50%;background:#07956f}.ps-summary-stats{display:grid;grid-template-columns:repeat(3,1fr)}.ps-summary-stats>span{border-right:1px solid #d7e0e8;text-align:center}.ps-summary-stats>span:last-child{border:0}.ps-summary-stats small,.ps-summary-stats strong,.ps-summary-stats em{display:block}.ps-summary-stats small{color:#667085;font-size:7px;text-transform:uppercase}.ps-summary-stats strong{color:#00416b;font-size:16px}.ps-summary-stats em{color:#98a2b3;font-size:7px;font-style:normal}.ps-summary-current{text-align:right}.ps-summary-current strong{display:block;margin-top:3px;color:#17243a;font-size:9px}.ps-summary-progress{grid-column:1/-1;height:5px;margin-top:-5px}.ps-toast{position:fixed;z-index:70;left:50%;bottom:30px;max-width:calc(100% - 30px);padding:11px 16px;border-radius:9px;color:#fff;background:#152536;font-size:11px;font-weight:700;opacity:0;transform:translate(-50%,20px);pointer-events:none;transition:.2s}.ps-toast.show{opacity:1;transform:translate(-50%,0)}
@media(max-width:1200px){.ps-session{grid-template-columns:1fr}.ps-workflow{border-top:1px solid var(--soft);border-left:0;display:grid;grid-template-columns:1fr 1.4fr;align-items:center;gap:20px}.ps-steps{margin-top:0}.ps-packing-grid{grid-template-columns:minmax(235px,3.2fr) minmax(470px,8.8fr)}.ps-weight-card{grid-template-columns:1fr 1fr;row-gap:13px}.ps-weight-card>:nth-child(3){border-left:0}}@media(max-width:900px){.ps-order-overview{grid-template-columns:1fr}.ps-order-progress,.ps-facts{grid-column:1}.ps-facts{grid-template-columns:repeat(3,1fr)}.ps-packing-grid{grid-template-columns:1fr}.ps-invoice-panel{position:static}.ps-summary{right:14px;width:calc(100vw - 28px)}}@media(max-width:650px){.ps-order-overview,.ps-workflow{padding:15px}.ps-facts{grid-template-columns:repeat(2,1fr)}.ps-workflow{display:block}.ps-steps{margin-top:15px}.ps-mode-grid,.ps-weight-card{grid-template-columns:1fr}.ps-weight-card>*{padding:11px 0;border-left:0!important;text-align:left}.ps-weight-card>*+*{border-top:1px solid #b9d4df}.ps-draft{display:none}.ps-summary{grid-template-columns:1fr}.ps-summary-title{display:none}.ps-summary-current{text-align:center}}
</style>
@endpush

@push('scripts')
<script>
$(function(){
    var $builder=$('#ps-builder');
    function toast(message){var $toast=$('#ps-toast').text(message).addClass('show');clearTimeout(window.psToastTimer);window.psToastTimer=setTimeout(function(){$toast.removeClass('show')},2200)}
    function setBuilder(collapsed){$builder.toggleClass('collapsed',collapsed);$('#ps-builder-toggle').attr('aria-expanded',!collapsed);$('#ps-collapse-all').text(collapsed?'Expand all':'Collapse all')}
    $('input[name="package_mode"]').on('change',function(){$('.ps-mode-card').removeClass('selected');$(this).closest('.ps-mode-card').addClass('selected');var sorted=this.value==='sorted';$('#ps-sorted-section').prop('hidden',!sorted);$('#ps-assorted-section').prop('hidden',sorted);$('#ps-weight-note').text(sorted?'Select a registered box.':'Add carton contents to calculate weight.')});
    $('#ps-template').on('change',function(){var items={moisturiser:{title:'Remark Daily Moisturiser 50g',units:'15 units',weight:'1,140 g',range:'1,115–1,165 g'},sunscreen:{title:'Remark Sunscreen SPF50 60ml',units:'12 units',weight:'1,020 g',range:'995–1,045 g'}},item=items[this.value];if(!item){$('#ps-template-preview').prop('hidden',true).empty();$('#ps-system-weight').text('0 g');$('#ps-weight-range').text('—');$('#ps-tolerance').text('± 0 g');return}$('#ps-template-preview').html('<strong>'+item.title+'</strong> · '+item.units+' per carton').prop('hidden',false);$('#ps-system-weight').text(item.weight);$('#ps-weight-range').text(item.range);$('#ps-tolerance').text('± 25 g');$('#ps-weight-note').text('Registered box weight.')});
    $('#ps-builder-toggle').on('click',function(e){if(!$(e.target).is('select,input,label'))setBuilder(!$builder.hasClass('collapsed'))}).on('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();setBuilder(!$builder.hasClass('collapsed'))}});
    $('#ps-collapse-all').on('click',function(){setBuilder(!$builder.hasClass('collapsed'))});
    $('.ps-search input').on('input',function(){var query=this.value.trim().toLowerCase();$('.ps-product').each(function(){$(this).prop('hidden',!!query&&!$(this).data('search').includes(query))})});
    $('#ps-summary-toggle').on('click',function(){$('#ps-summary').toggleClass('collapsed')});
    $('#ps-clear').on('click',function(){$('input[name="package_mode"][value="sorted"]').prop('checked',true).trigger('change');$('#ps-template').val('').trigger('change');$('#ps-carton-count').val(1);$('#ps-manual-weight').val(0);toast('Draft carton cleared.')});
    $('#ps-add-carton').on('click',function(){if($('input[name="package_mode"]:checked').val()==='sorted'&&!$('#ps-template').val()){toast('Select a pre-packed box template first.');return}toast('Static preview only — carton is ready to add.')});
});
</script>
@endpush
